 static Settings Clone(Settings value){var json=new JavaScriptSerializer();return json.Deserialize<Settings>(json.Serialize(value));}
 void ReloadProfiles(){profileList.Items.Clear();foreach(var profile in profiles)profileList.Items.Add(profile);if(profileList.Items.Count>0)profileList.SelectedItem=profileList.Items[0];}
 void SetDeviceSelections(Settings next){
  var monitor=monitors.Items.Cast<Choice>().FirstOrDefault(c=>c.Id==next.MonitorId);if(monitor==null){monitor=new Choice(next.MonitorId,"Saved display (currently unavailable)");monitors.Items.Add(monitor);}monitors.SelectedItem=monitor;
  var output=audio.Items.Cast<Choice>().FirstOrDefault(c=>c.Id==next.AudioId);if(output==null){output=new Choice(next.AudioId,"Saved audio (currently unavailable)");audio.Items.Add(output);}audio.SelectedItem=output;launcher.SelectedItem=launcher.Items.Cast<Choice>().First(c=>c.Id==next.Launcher);steamPath.Text=next.SteamPath;SetOtherMonitorMode(next);steam.Checked=next.LaunchSteam;SetVideoPreferences(next);SetCec(next);SetGoogleTv(next);playnitePath.Text=next.PlaynitePath;
 }
 void SaveFeatureSettings(Settings next){next.ControllerShortcut=controllerEnabled.Checked;next.ControllerMask=int.Parse(((Choice)controllerChord.SelectedItem).Id);next.ControllerHoldSeconds=(int)controllerSeconds.Value;next.KeepAwake=awakeEnabled.Checked;next.CheckUpdates=updateChecks.Checked;next.AutoUpdate=automaticUpdates.Checked;next.SetupCompleted=settings.SetupCompleted;SaveQuickMenu(next);SaveOptional(next);SaveCec(next);SaveGoogleTv(next);controllers.Reset();}
 void LayoutFeatures(int width){
  var cards=new[]{controllerOptions,awakeOptions,profilesCard,updatesCard,supportCard};int[] pages={2,2,3,4,4},ys={504,692,8,8,276},heights={176,94,308,250,220};
