 void UpdateFeatureMode(){if(awakeInfo==null||awakeEnabled==null)return;awakeInfo.Text=engine.Active?(settings.KeepAwake?"Active during this TV session. Released automatically on return to desktop.":"Off for this TV session. Enable and save to prevent idle sleep."):"Inactive in desktop mode. Your preference is saved.";if(!uiTest)try{awake.Update(engine.Active,settings.KeepAwake);}catch(Exception e){Storage.Log(e.ToString());awakeInfo.Text=e.Message;}installUpdate.Enabled=availableUpdate!=null&&!engine.Active&&!busy&&!installingUpdate;}
 async Task StartFeatures(){
  controllerTimer.Start();updateTimer.Start();couchTimer.Start();try{if(File.Exists(Storage.PathOf("update-history.json")))updateHistory=Storage.Read<UpdateHistory>("update-history.json");}catch(Exception e){Storage.Log(e.ToString());}
  if(!settings.SetupCompleted&&string.IsNullOrWhiteSpace(settings.MonitorId)&&!engine.Active)await RunWizard();
  if(settings.CheckUpdates&&DateTime.UtcNow-updateHistory.LastCheckUtc>TimeSpan.FromDays(1))await CheckForUpdates(false);
 }
 void DisposeFeatures(){couchTimer.Stop();couchTimer.Dispose();if(quickMenu!=null&&!quickMenu.IsDisposed)quickMenu.Close();controllerTimer.Stop();updateTimer.Stop();controllerTimer.Dispose();updateTimer.Dispose();awake.Dispose();}
 async Task CheckForUpdates(bool manual){
  if(checkingUpdate||installingUpdate)return;checkingUpdate=true;checkUpdate.Enabled=false;updateInfo.Text="Checking GitHub...";
  try{availableUpdate=await Task.Run(()=>UpdateService.Check());updateHistory.LastCheckUtc=DateTime.UtcNow;Storage.Save("update-history.json",updateHistory);updateInfo.Text=availableUpdate==null?"You're up to date. Installed version: "+UpdateService.Current:"Version "+availableUpdate.Version+" is available. Your settings will be kept.";if(availableUpdate!=null&&updateHistory.NotifiedVersion!=availableUpdate.Version){updateHistory.NotifiedVersion=availableUpdate.Version;Storage.Save("update-history.json",updateHistory);if(!uiTest)tray.ShowBalloonTip(5000,"SteamCouch update available","Version "+availableUpdate.Version+" — open Help & updates to install.",ToolTipIcon.Info);}}
  catch(Exception e){updateHistory.LastCheckUtc=DateTime.UtcNow;try{Storage.Save("update-history.json",updateHistory);}catch{}updateInfo.Text="Couldn't check right now. Try again later.";Storage.Log(e.ToString());if(manual)ShowError(e);}finally{checkingUpdate=false;checkUpdate.Enabled=true;UpdateFeatureMode();}
 }
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)] struct LastInput {public uint Size,Time;}
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern bool GetLastInputInfo(ref LastInput input);
 bool BackgroundUpdateAllowed(){var input=new LastInput{Size=8};return !engine.Active&&!Visible&&!busy&&OwnedForms.Length==0&&!SteamClient.IsBigPictureOpen()&&!PlayniteClient.Running&&controllers.Idle&&GetLastInputInfo(ref input)&&unchecked((uint)Environment.TickCount-input.Time)>=60000;}
 async Task InstallAvailableUpdate(){
  if(availableUpdate==null||busy||installingUpdate)return;bool background=!Visible;if(background&&!BackgroundUpdateAllowed())return;if(engine.Active||SteamClient.IsBigPictureOpen()){ShowError(new InvalidOperationException("Return to desktop and close Big Picture before installing an update."));return;}installingUpdate=true;busy=true;controllers.Reset();installUpdate.Enabled=false;checkUpdate.Enabled=false;save.Enabled=false;toggle.Enabled=false;updateInfo.Text="Downloading and checking the update...";
  try{string files=await Task.Run(()=>UpdateService.Download(availableUpdate));if(engine.Active)throw new InvalidOperationException("Return to desktop before updating.");UpdateService.Install(files,background);quitting=true;Close();}
  catch(Exception e){installingUpdate=false;busy=false;updateInfo.Text="Update wasn't installed. Your current version is unchanged.";save.Enabled=true;toggle.Enabled=true;checkUpdate.Enabled=true;UpdateFeatureMode();ShowError(e);}
 }
 async Task RunWizard(){
  if(busy||installingUpdate)return;if(engine.Active){ShowError(new InvalidOperationException("Return to desktop before running setup."));return;}controllers.Reset();
  try{var displays=await Task.Run(()=>devices.Monitors());var outputs=await Task.Run(()=>devices.Audio());using(var wizard=new SetupWizard(Clone(settings),displays,outputs,engine)){wizard.Icon=Icon;if(wizard.ShowDialog(this)==DialogResult.OK){SetDeviceSelections(wizard.Result);settings.SetupCompleted=true;Save();status.Text="Setup complete. Your couch is ready.";}}UpdateMode();}
  catch(Exception e){ShowError(e);}finally{controllers.Reset();UpdateMode();}
 }
 async Task Troubleshoot(){
  if(busy||installingUpdate)return;try{
   string report=await Task.Run(()=>{var displays=devices.Monitors();var outputs=devices.Audio();var tv=displays.FirstOrDefault(d=>d.Get("Monitor ID")==settings.MonitorId);var audioDevice=outputs.FirstOrDefault(a=>a.Get("Item ID")==settings.AudioId);return "SteamCouch "+UpdateService.Current+"\r\nChecked: "+DateTime.Now.ToString("g")+"\r\n\r\n"+(engine.Active?"TV session / recovery point exists. Restore desktop before changing profiles.":"Desktop mode. No TV recovery point.")+"\r\n\r\nTV: "+(tv==null?"Not found — check power/cable and refresh devices.":tv.Get("Monitor Name")+" — "+(Engine.IsOn(tv)?"connected":"disconnected; SteamCouch will reconnect it"))+"\r\nAudio: "+(string.IsNullOrEmpty(settings.AudioId)?"Automatic TV audio":audioDevice==null?"Not found — wake the TV and refresh devices.":audioDevice.Get("Name")+" — "+audioDevice.Get("Device State"))+"\r\nGaming mode: "+settings.Launcher+"\r\nSteam program: "+(File.Exists(settings.SteamPath)?"Found":"Not found; select Steam.exe in Settings")+"\r\nXbox mode supported: "+XboxClient.Supported+"\r\nController shortcut: "+(settings.ControllerShortcut?"Enabled":"Disabled")+"; connected controllers: "+controllers.Connected+"\r\nKeep awake preference: "+settings.KeepAwake+"; active request: "+awake.Active+"\r\n\r\nIf audio is wrong, select the TV output explicitly. If Steam opens elsewhere, use Steam's Automatic/Primary display setting. For failed restores, reconnect the original displays and retry Restore desktop.\r\n\r\nThis report includes device names, but omits device IDs, account names, and local file paths.";});
   using(var dialog=new Form{Text="SteamCouch — Troubleshoot",BackColor=Theme.Background,ForeColor=Theme.Text,ClientSize=new Size(760,560),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,AutoScaleMode=AutoScaleMode.Dpi,AutoScaleDimensions=new SizeF(96,96)}){var text=new RichTextBox{Text=report,ReadOnly=true,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",10),Dock=DockStyle.Fill};dialog.Controls.Add(text);var footer=new Panel{Dock=DockStyle.Bottom,Height=64};var export=new ModernButton{Text="Save report",Primary=true};Theme.Place(footer,export,24,12,150,38);export.Click+=delegate{using(var picker=new SaveFileDialog{Filter="Text report|*.txt",FileName="SteamCouch-report.txt"})if(picker.ShowDialog(dialog)==DialogResult.OK)File.WriteAllText(picker.FileName,report);};dialog.Controls.Add(footer);dialog.Shown+=delegate{Theme.DarkTitle(dialog);};dialog.ShowDialog(this);}
  }catch(Exception e){ShowError(e);}
 }
 void CheckFeatureBindings(){
  string path=Storage.PathOf("settings.json"),original=File.ReadAllText(path);var before=Clone(settings);
  try{controllerEnabled.Checked=!before.ControllerShortcut;awakeEnabled.Checked=!before.KeepAwake;automaticUpdates.Checked=!before.AutoUpdate;updateChecks.Checked=!before.CheckUpdates;controllerChord.SelectedItem=controllerChord.Items[1];controllerSeconds.Value=3;quickMenuEnabled.Checked=!before.QuickMenu;menuChord.SelectedItem=menuChord.Items[1];hdrPreference.SelectedItem=hdrPreference.Items[1];vrrSession.Checked=!before.TvVrr;Save();var saved=Storage.Read<Settings>("settings.json");if(saved.ControllerShortcut==before.ControllerShortcut||saved.KeepAwake==before.KeepAwake||saved.AutoUpdate==before.AutoUpdate||saved.CheckUpdates==before.CheckUpdates||saved.ControllerMask!=48||saved.ControllerHoldSeconds!=3||saved.QuickMenu==before.QuickMenu||saved.MenuMask!=16416||saved.TvHdr!="On"||saved.TvVrr==before.TvVrr)throw new Exception("Feature controls did not persist.");}
  finally{File.WriteAllText(path,original);settings=before;controllerEnabled.Checked=before.ControllerShortcut;awakeEnabled.Checked=before.KeepAwake;automaticUpdates.Checked=before.AutoUpdate;updateChecks.Checked=before.CheckUpdates;controllerChord.SelectedItem=controllerChord.Items.Cast<Choice>().First(c=>c.Id==before.ControllerMask.ToString());controllerSeconds.Value=before.ControllerHoldSeconds;quickMenuEnabled.Checked=before.QuickMenu;menuChord.SelectedItem=menuChord.Items.Cast<Choice>().First(c=>c.Id==before.MenuMask.ToString());SetVideoPreferences(before);UpdateMode();}
 }
 void PreviewWizard(){using(var wizard=new SetupWizard(Clone(settings),devices.Monitors(),devices.Audio(),engine)){wizard.Icon=Icon;wizard.Show(this);for(int step=0;step<5;step++){wizard.PreviewStep(step);wizard.Refresh();using(var bitmap=new Bitmap(wizard.Width,wizard.Height)){wizard.DrawToBitmap(bitmap,new Rectangle(0,0,wizard.Width,wizard.Height));bitmap.Save(Storage.PathOf("wizard-"+step+".png"));}}wizard.Close();}using(var dialog=new GoogleTvDialog(Clone(settings))){dialog.Icon=Icon;dialog.Show(this);dialog.Refresh();using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,dialog.Width,dialog.Height));bitmap.Save(Storage.PathOf("google-tv-wizard.png"));}dialog.Close();}using(var guide=new GoogleTvGuide()){guide.Icon=Icon;guide.Show(this);Application.DoEvents();guide.Refresh();using(var bitmap=new Bitmap(guide.Width,guide.Height)){guide.DrawToBitmap(bitmap,new Rectangle(0,0,guide.Width,guide.Height));bitmap.Save(Storage.PathOf("google-tv-guide.png"));}guide.Close();}}
}
